namespace {
struct Buffer { vk::Buffer buffer{}; VmaAllocation allocation{}; vk::DeviceSize size{}; };
Buffer make_buffer(vulkan_runtime::core::VulkanContext const& ctx, vk::DeviceSize size, vk::BufferUsageFlags usage, VmaMemoryUsage mem, VmaAllocationCreateFlags flags = 0) { VkBufferCreateInfo ci{}; ci.sType=VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO; ci.size=size; ci.usage=static_cast<VkBufferUsageFlags>(usage); ci.sharingMode=VK_SHARING_MODE_EXCLUSIVE; VmaAllocationCreateInfo ai{}; ai.usage=mem; ai.flags=flags; VkBuffer b{}; VmaAllocation a{}; if(vmaCreateBuffer(ctx.allocator,&ci,&ai,&b,&a,nullptr)!=VK_SUCCESS) throw std::runtime_error("buffer"); return {vk::Buffer(b),a,size}; }
void destroy(vulkan_runtime::core::VulkanContext const& ctx, Buffer& b){if(b.allocation)vmaDestroyBuffer(ctx.allocator,static_cast<VkBuffer>(b.buffer),b.allocation);b.allocation=nullptr;}
}
int main(){try{using namespace vulkan_runtime::core;constexpr uint32_t rows=3,hidden=64;const size_t n=rows*hidden;auto ctx=create_context("rmsnorm-backward");std::vector<float>x(n),g(hidden,.8f),dy(n),gpu(n);for(size_t i=0;i<n;++i){x[i]=.01f*float(int(i%17)-8);dy[i]=.02f*float(int(i%13)-6);}auto bx=make_buffer(ctx,n*4,vk::BufferUsageFlagBits::eStorageBuffer|vk::BufferUsageFlagBits::eTransferDst,VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE),bg=make_buffer(ctx,hidden*4,vk::BufferUsageFlagBits::eStorageBuffer|vk::BufferUsageFlagBits::eTransferDst,VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE),bd=make_buffer(ctx,n*4,vk::BufferUsageFlagBits::eStorageBuffer|vk::BufferUsageFlagBits::eTransferDst,VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE),bo=make_buffer(ctx,n*4,vk::BufferUsageFlagBits::eStorageBuffer|vk::BufferUsageFlagBits::eTransferSrc,VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE),st=make_buffer(ctx,(2*n+hidden+n)*4,vk::BufferUsageFlagBits::eTransferSrc|vk::BufferUsageFlagBits::eTransferDst,VMA_MEMORY_USAGE_AUTO_PREFER_HOST,VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT);void*m=nullptr;vmaMapMemory(ctx.allocator,st.allocation,&m);auto*f=static_cast<float*>(m);std::memcpy(f,x.data(),n*4);std::memcpy(f+n,g.data(),hidden*4);std::memcpy(f+n+hidden,dy.data(),n*4);vmaFlushAllocation(ctx.allocator,st.allocation,0,(2*n+hidden)*4);vmaUnmapMemory(ctx.allocator,st.allocation);auto blob=vulkan_runtime::shaders::get("rmsnorm_backward.spv");auto sm=ctx.device.createShaderModule(vk::ShaderModuleCreateInfo{}.setCodeSize(blob.size).setPCode(reinterpret_cast<uint32_t const*>(blob.data)));std::array<vk::DescriptorSetLayoutBinding,4>lbs{};for(uint32_t i=0;i<4;++i)lbs[i].setBinding(i).setDescriptorType(vk::DescriptorType::eStorageBuffer).setDescriptorCount(1).setStageFlags(vk::ShaderStageFlagBits::eCompute);auto sl=ctx.device.createDescriptorSetLayout(vk::DescriptorSetLayoutCreateInfo{}.setBindings(lbs));auto pl=ctx.device.createPipelineLayout(vk::PipelineLayoutCreateInfo{}.setSetLayouts(sl).setPushConstantRanges(vk::PushConstantRange{}.setStageFlags(vk::ShaderStageFlagBits::eCompute).setSize(8)));auto pp=ctx.device.createComputePipeline({},vk::ComputePipelineCreateInfo{}.setStage(vk::PipelineShaderStageCreateInfo{}.setStage(vk::ShaderStageFlagBits::eCompute).setModule(sm).setPName("main")).setLayout(pl));auto pool=ctx.device.createDescriptorPool(vk::DescriptorPoolCreateInfo{}.setMaxSets(1).setPoolSizes(vk::DescriptorPoolSize{}.setType(vk::DescriptorType::eStorageBuffer).setDescriptorCount(4)));auto set=ctx.device.allocateDescriptorSets(vk::DescriptorSetAllocateInfo{}.setDescriptorPool(pool).setSetLayouts(sl)).front();std::array<vk::DescriptorBufferInfo,4>bi{};bi[0].setBuffer(bx.buffer).setRange(n*4);bi[1].setBuffer(bg.buffer).setRange(hidden*4);bi[2].setBuffer(bd.buffer).setRange(n*4);bi[3].setBuffer(bo.buffer).setRange(n*4);std::array<vk::WriteDescriptorSet,4>w{};for(uint32_t i=0;i<4;++i)w[i].setDstSet(set).setDstBinding(i).setDescriptorType(vk::DescriptorType::eStorageBuffer).setDescriptorCount(1).setBufferInfo(bi[i]);ctx.device.updateDescriptorSets(w,{});auto cp=ctx.device.createCommandPool(vk::CommandPoolCreateInfo{}.setQueueFamilyIndex(ctx.computeQueueFamily));auto cmd=ctx.device.allocateCommandBuffers(vk::CommandBufferAllocateInfo{}.setCommandPool(cp).setCommandBufferCount(1)).front();cmd.begin(vk::CommandBufferBeginInfo{});cmd.copyBuffer(st.buffer,bx.buffer,vk::BufferCopy{}.setSize(n*4));cmd.copyBuffer(st.buffer,bg.buffer,vk::BufferCopy{}.setSrcOffset(n*4).setSize(hidden*4));cmd.copyBuffer(st.buffer,bd.buffer,vk::BufferCopy{}.setSrcOffset((n+hidden)*4).setSize(n*4));cmd.pipelineBarrier(vk::PipelineStageFlagBits::eTransfer,vk::PipelineStageFlagBits::eComputeShader,{},vk::MemoryBarrier{vk::AccessFlagBits::eTransferWrite,vk::AccessFlagBits::eShaderRead},{},{});cmd.bindPipeline(vk::PipelineBindPoint::eCompute,pp.value);cmd.bindDescriptorSets(vk::PipelineBindPoint::eCompute,pl,0,set,{});uint32_t pc[2]={rows,hidden};cmd.pushConstants(pl,vk::ShaderStageFlagBits::eCompute,0,8,pc);cmd.dispatch(rows,1,1);cmd.pipelineBarrier(vk::PipelineStageFlagBits::eComputeShader,vk::PipelineStageFlagBits::eTransfer,{},vk::MemoryBarrier{vk::AccessFlagBits::eShaderWrite,vk::AccessFlagBits::eTransferRead},{},{});cmd.copyBuffer(bo.buffer,st.buffer,vk::BufferCopy{}.setDstOffset((2*n+hidden)*4).setSize(n*4));cmd.end();ctx.computeQueue.submit(vk::SubmitInfo{}.setCommandBuffers(cmd));ctx.computeQueue.waitIdle();vmaMapMemory(ctx.allocator,st.allocation,&m);vmaInvalidateAllocation(ctx.allocator,st.allocation,(2*n+hidden)*4,n*4);std::memcpy(gpu.data(),static_cast<char*>(m)+(2*n+hidden)*4,n*4);vmaUnmapMemory(ctx.allocator,st.allocation);double maxe=0;for(uint32_t r=0;r<rows;++r){double ss=0,dot=0;for(uint32_t i=0;i<hidden;++i){ss+=x[r*hidden+i]*x[r*hidden+i];dot+=x[r*hidden+i]*dy[r*hidden+i]*g[i];}double inv=1/std::sqrt(ss/hidden+1e-5),c=dot*inv*inv*inv/hidden;for(uint32_t i=0;i<hidden;++i)maxe=std::max(maxe,std::abs(double(gpu[r*hidden+i])-(g[i]*inv*dy[r*hidden+i]-x[r*hidden+i]*c)));}destroy(ctx,bx);destroy(ctx,bg);destroy(ctx,bd);destroy(ctx,bo);destroy(ctx,st);if(maxe>2e-4){std::cerr<<"RMSNorm backward mismatch max="<<maxe<<" gpu0="<<gpu[0]<<" gpu8="<<gpu[8]<<"\n";return 1;}std::cout<<"RMSNorm backward: PASS max="<<maxe<<"\n";return 0;}catch(std::exception const&e){std::cerr<<e.what()<<"\n";return 1;}}
